import json
from pathlib import Path
p=Path(__file__).resolve().parents[1]/'data'
def get(n):return json.loads((p/(n+'.json')).read_text())
def save(n,x):(p/(n+'.json')).write_text(json.dumps(x,ensure_ascii=False,indent=2))
def add(cat,name,slug,url,fields,version,typ):
 d=get(cat);e=next((x for x in d if x['slug']==slug),None)
 if not e:
  e={'slug':slug,'name':name,'category':cat,'type':typ,'purchase':'нет данных','sale':'нет данных','obtain':'нет данных','use':'нет данных','features':'нет данных','versions':version,'sources':[],'image':None,'links':[],'event':'нет данных','prior_records':[]};d.append(e)
 e['prior_records']=[x for x in e['prior_records'] if x.get('original_id')!=slug]+[{'original_id':slug,'original_category':typ,'version':version,'date':'дата редакции не установлена','fields':fields,'confidence':'Историческая фанатская страница. Текст перенесён с сохранением опечаток; если награда показана только неподписанной пиктограммой, приведён путь файла без расшифровки.'}]
 if not any(x['url']==url for x in e['sources']):e['sources'].append({'url':url,'label':'Прочитанная страница Zombaks' if 'zombaks.ucoz' in url else 'Прочитанная историческая новость'})
 save(cat,d)
